import{_ as o,o as e,c as r,ag as i}from"./chunks/framework.DzGOF12C.js";const _=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"philosophy/Epistemology/07. 지식의 정의.md","filePath":"philosophy/Epistemology/07. 지식의 정의.md"}'),l={name:"philosophy/Epistemology/07. 지식의 정의.md"};function s(a,t,n,p,u,g){return e(),r("div",null,[...t[0]||(t[0]=[i('<h2 id="안다-는-것" tabindex="-1">&#39;안다&#39;는 것 <a class="header-anchor" href="#안다-는-것" aria-label="Permalink to &quot;&#39;안다&#39;는 것&quot;">​</a></h2><p>세 가지 물음으로 나눌 수 있음</p><ol><li>(지식이란) 무엇인가</li><li>어떻게 가능한가</li><li>얼마나, 어디까지 가능한가</li></ol><h2 id="진리-이론" tabindex="-1">진리 이론 <a class="header-anchor" href="#진리-이론" aria-label="Permalink to &quot;진리 이론&quot;">​</a></h2><p><strong>진리대응론(Correspondence Theory)</strong>: 명제는 그에 대응하는 사실과 일치할 때 참. 인식주체의 믿음과 무관하게, 참·거짓 여부가 사실과의 대응으로 결정됨.</p><ul><li>문제 1: 어떤 사실과 대응되어야 하는가? — 언어적인 명제와 비언어적 사실 사이의 대응을 설명하기 어려움. &quot;사실이란 무엇인가?&quot;에 답하려 하면 결국 &quot;명제의 참을 증명해주는 것&quot;이 되어 순환논증에 빠짐</li><li>문제 2: &#39;일치된다&#39;는 것은 정확히 어떤 상태를 말하는가?</li></ul><p><strong>정합론(Coherence Theory)</strong>: 명제는 다른 명제들과 정합적으로 부합할 때 참.</p><ul><li>비판: 인식적 <strong>정당성</strong>과 <strong>참</strong>을 혼동하고 있음 (정합적이라고 해서 반드시 참인 것은 아님)</li></ul><p><strong>실용론(Pragmatic Theory)</strong>: 명제에 대한 믿음이 유용할 때 참.</p><ul><li>비판: 참인 믿음과 유용한 믿음이 반드시 동일하지는 않음</li></ul><h2 id="인식정당성-조건" tabindex="-1">인식정당성 조건 <a class="header-anchor" href="#인식정당성-조건" aria-label="Permalink to &quot;인식정당성 조건&quot;">​</a></h2><p>모든 참인 믿음이 지식인 것은 아님 — 지식이려면 적절한 근거에 토대를 두어야 함. (예: 중력을 신을 통해 설명해 우연히 참에 이르렀다면, 이것을 지식이라 할 수 있는가?)</p><p><strong>정당성의 종류</strong></p><ol><li><strong>실용적 정당성</strong>: 할 수 있다는 믿음을 갖는 것 자체가 실용적으로 정당함</li><li><strong>도덕적 정당성</strong></li><li><strong>인식적 정당성</strong>: 인식 행위의 목적인 진리 추구·거짓 회피에 부합하는 정당성</li></ol><p><strong>정당성과 참의 독립성</strong></p><ul><li>명제는 참이지만, 그 명제에 대한 믿음은 정당하지 않을 수 있음</li><li>명제에 대한 믿음은 정당하지만, 그 명제는 참이 아닐 수 있음 — 합리적 과정을 거쳐 믿음을 형성했음에도 결과적으로 거짓일 수 있음</li><li>정당성은 <strong>상대적</strong>이며 정도에 따라 구별될 수 있음</li></ul><p><strong>정당하다고 믿는 것 vs 정당화하는 것</strong>: 어떤 명제에 대한 믿음이 누군가에게 정당하다는 것과, 그 사람이 그 명제를 (외적으로) 정당화한다는 것은 서로 다른 문제 — 예: &quot;내 앞에 책상이 있다&quot;는 명제에 대한 믿음은 (별도로 논증하며) 정당화하지 않아도 정당할 수 있음.</p><h2 id="지식의-전통적-정의-jtb-justified-true-belief" tabindex="-1">지식의 전통적 정의 (JTB: Justified True Belief) <a class="header-anchor" href="#지식의-전통적-정의-jtb-justified-true-belief" aria-label="Permalink to &quot;지식의 전통적 정의 (JTB: Justified True Belief)&quot;">​</a></h2><p>믿음(Belief), 진리(Truth), 인식정당성(Justification) 세 조건은 지식의 <strong>필요조건</strong>이 될 수 있지만, 세 조건을 모두 갖췄다고 해서 지식이 되는 <strong>충분조건</strong>은 아님 — 이 문제를 드러내는 것이 [[08. 게티어 문제|게티어 문제]].</p>',19)])])}const d=o(l,[["render",s]]);export{_ as __pageData,d as default};
